/tmp/opensip-architecture-review-env/bin/python -I -B -c "
import json
N='/private/tmp/opensip-design-corrections/claude-independent-design.v44/work/source44/docs/coop/design-corrections/native/'
t=json.load(open(N+'typescript-protocol2-order.v1.json'))
print('TS keys',sorted(t)); print('wild',json.dumps(t['wildcards'])); print('init',t['initialState']); print('obs',t.get('eventObservations'))
for r in t['rules']: print(r['id'],r['phase'],r['frame'],r.get('guard',{}),'->',r['next'],r.get('terminal',''))
p=json.load(open(N+'protocol3-transitions.v1.json'))
print('P3 keys',sorted(p)); print('init',p['initialState']); print('derived',json.dumps(p.get('derivedObservations'))[:600]); print('rowPayloads',json.dumps(p.get('rowPayloads'))[:1500])
for r in p['rules']: print(r['id'],r['phase'],r['frame'],r.get('guard',{}),'->',r['next'],r.get('terminal',''))
b=json.load(open(N+'native-evidence.schemas.v2.json'))
for k,v in b['\$defs'].items():
  if any(x in k for x in ('Hello','OpenUniverse','UniverseAccepted','Coverage','Unavailable','Limits','Cancel','BudgetExhausted')): print('BUNDLE',k,v.get('required'),v.get('additionalProperties'))
h=json.load(open(N+'provider-handshake.schemas.v1.json')); s=json.load(open(N+'provider-startup.schemas.v1.json'))
print('H x-keys',[k for k in h if k.startswith('x-')], sorted(h['x-opensip-wire-law'])); print('S x-keys',[k for k in s if k.startswith('x-')], sorted(s['x-opensip-startup-law']))
for k,v in list(h['\$defs'].items())+list(s['\$defs'].items()): print('DEF',k,v.get('required'))
"

