    for k,v in o.items():
      if k==name: print('RUSTV2',path+'/'+k,json.dumps(v)[:900])
      find(v,name,path+'/'+k)
  elif isinstance(o,list):
    for i,v in enumerate(o): find(v,name,path+'[%d]'%i)
for n in ('HelloV2','HelloAckV2','ExpectedRustIdentityV2','CancelledV2','protocolIdentity'): find(r,n)
h=json.load(open(N+'provider-handshake.schemas.v1.json')); s=json.load(open(N+'provider-startup.schemas.v1.json')); b=json.load(open(N+'native-evidence.schemas.v2.json'))
print('H ExpectedRustIdentityV3',json.dumps(h['\$defs']['ExpectedRustIdentityV3']['properties']))
